% 示例 1：基础与显示
% 演示变量赋值、不加分号时的自动显示、format long 以及 fprintf 格式化输出
clear;
a = 7            % 不加分号：自动显示变量的值
b = 2.5;         % 加分号：不显示
c = a * b        % 乘法结果会被显示
name = '圆周率';
v = [1 2 3 4]    % 行向量
% 默认 format short：保留 4 位小数
p = pi
% 切换为 format long：显示更多有效数字
format long
p = pi
format short     % 恢复默认格式
% fprintf：按格式字符串输出
fprintf('a = %d, b = %.2f\n', a, b);
fprintf('%s 约等于 %.6f\n', name, pi);
fprintf('科学计数法：%e\n', 12345.678);
% fprintf 会循环使用格式，逐个输出向量元素
fprintf('元素：%d\n', v);
% disp 只显示值，不显示变量名
disp('计算完成！');
disp(c);
cls = class(c)   % 查看变量的数据类型

% 示例 5：元胞数组与结构体
% 元胞数组可以存放不同类型的数据；结构体用字段组织数据
c = {42, 'MATLAB', [1 2 3]; true, int8(7), @sin}
class(c{1,2})          % 用花括号取出内容
% cellfun：对每个元胞应用函数
lens = cellfun(@numel, c)
names = {'苹果', '香蕉', '樱桃'};
% UniformOutput 为 false 时返回元胞数组
tagged = cellfun(@(s) ['水果:' s], names, 'UniformOutput', false)
% 结构体数组：每个元素有相同的字段
students(1).name = '张三'; students(1).score = 88;
students(2).name = '李四'; students(2).score = 95;
students(3).name = '王五'; students(3).score = 72;
students
% fieldnames：列出所有字段名
f = fieldnames(students)
% 提取所有分数组成向量
allScores = [students.score]
[~, best] = max(allScores);
fprintf('最高分：%s（%d 分）\n', students(best).name, allScores(best));
% 用 struct 函数一次创建，并动态访问字段
p = struct('x', 1, 'y', 2);
fld = 'y';
p.(fld) = 10;
disp(p);
isfield(p, 'z')

% 示例 6：函数文件与匿名函数
% stats 定义在单独的函数文件 stats.m 中，返回均值和标准差两个输出
data = [2 4 4 4 5 5 7 9];
[m, s] = stats(data);
fprintf('均值 = %.4f，标准差 = %.4f\n', m, s);
% 只接收第一个输出
onlyMean = stats([10 20 30])
% 匿名函数：@(参数) 表达式
sq = @(x) x.^2;
f = @(x, y) sqrt(x.^2 + y.^2);
sq(5)
f(3, 4)
% 匿名函数可以捕获当前工作区的变量
k = 3;
scale = @(x) k * x;
scale(7)
% arrayfun：对数组每个元素调用函数
fact = arrayfun(@(n) prod(1:n), 1:6)
% 函数句柄作为参数传递
g = @(t) exp(-t) .* cos(2*pi*t);
area = integral(g, 0, 2);
fprintf('积分结果 = %.6f\n', area);
% 用 fzero 求方程 cos(x) = x 的根
root = fzero(@(x) cos(x) - x, 0.5)

% 示例 7：正弦余弦绘图
% 演示 plot 的线型规格（LineSpec）、图例、标题、坐标轴标签和网格
x = linspace(0, 2*pi, 100);   % 0 到 2π 之间取 100 个点
y1 = sin(x);
y2 = cos(x);
y3 = sin(x) .* cos(x);
figure;
% 'r-' 红色实线，'b--' 蓝色虚线
plot(x, y1, 'r-', 'LineWidth', 2);
hold on;                       % 保持当前图形，继续叠加
plot(x, y2, 'b--', 'LineWidth', 2);
% 'g:' 绿色点线；每隔 10 个点画一个圆圈标记
plot(x, y3, 'g:');
plot(x(1:10:end), y1(1:10:end), 'ko');
hold off;
legend('sin(x)', 'cos(x)', 'sin(x)cos(x)', '采样点');
title('正弦与余弦函数');
xlabel('x（弧度）');
ylabel('函数值');
grid on;                       % 打开网格
axis([0 2*pi -1.2 1.2]);       % 设置坐标范围
% 输出几个关键点的数值
fprintf('sin(pi/2) = %.4f, cos(pi) = %.4f\n', sin(pi/2), cos(pi));

% 示例 8：子图画廊
% 用 subplot(2,2,k) 在一个窗口中排列 4 种常见图表
rng(42);                         % 固定随机种子，保证结果可重复
figure;
% 1. 柱状图
subplot(2, 2, 1);
sales = [23 45 31 52 38];
bar(sales);
title('柱状图：月销量');
xlabel('月份'); ylabel('销量');
% 2. 饼图
subplot(2, 2, 2);
share = [40 25 20 15];
pie(share);
title('饼图：市场份额');
% 3. 直方图：标准正态分布随机数
subplot(2, 2, 3);
r = randn(1000, 1);
histogram(r, 20);
title('直方图：randn');
% 4. 散点图
subplot(2, 2, 4);
xs = rand(1, 50);
ys = 2 * xs + 0.3 * randn(1, 50);
scatter(xs, ys, 'filled');
title('散点图'); xlabel('x'); ylabel('y');
% 打印随机样本的统计量
fprintf('randn 样本均值 = %.3f，标准差 = %.3f\n', mean(r), std(r));

% 示例 9：三维曲面
% peaks 是 MATLAB 自带的示例函数，常用于演示三维绘图
[X, Y, Z] = peaks(40);           % 生成 40×40 的网格数据
fprintf('网格大小：%d × %d\n', size(Z, 1), size(Z, 2));
fprintf('Z 的最大值 = %.3f，最小值 = %.3f\n', max(Z(:)), min(Z(:)));
figure;
surf(X, Y, Z);                   % 绘制三维曲面
colorbar;                        % 显示颜色条
title('peaks 函数曲面');
xlabel('X'); ylabel('Y'); zlabel('Z');
view(45, 30);                    % 方位角 45°，仰角 30°
% 自己构造一个曲面：z = sin(r)/r（墨西哥帽）
[x, y] = meshgrid(-8:0.5:8);
r = sqrt(x.^2 + y.^2) + eps;     % 加 eps 避免除以 0
z = sin(r) ./ r;
figure;
surf(x, y, z);
colorbar;
title('sin(r)/r 曲面');
view(3);                         % 默认三维视角

% 示例 10：常微分方程 ode45
% 阻尼振动方程：x'' + 2*zeta*w*x' + w^2*x = 0
% 改写为一阶方程组：y1 = x, y2 = x'
w = 2*pi;        % 固有角频率
zeta = 0.1;      % 阻尼比
odefun = @(t, y) [y(2); -2*zeta*w*y(2) - w^2*y(1)];
tspan = [0 5];   % 时间区间
y0 = [1; 0];     % 初始位移 1，初始速度 0
[t, y] = ode45(odefun, tspan, y0);
fprintf('求解步数：%d\n', numel(t));
fprintf('t = 5 时位移 = %.4f\n', y(end, 1));
% 与解析包络 exp(-zeta*w*t) 比较
env = exp(-zeta * w * t);
figure;
plot(t, y(:,1), 'b-', 'LineWidth', 1.5);
hold on;
plot(t, env, 'r--', t, -env, 'r--');
hold off;
legend('位移 x(t)', '包络线');
title('阻尼振动（ode45 数值解）');
xlabel('时间 t (s)'); ylabel('位移');
grid on;
% 相平面图：速度对位移
figure;
plot(y(:,1), y(:,2), 'm');
title('相平面轨迹'); xlabel('x'); ylabel('dx/dt');
grid on;

% 示例 11：多项式曲线拟合
% 用 polyfit 对带噪声的数据进行最小二乘多项式拟合，用 polyval 求值
rng(1);
x = 0:0.5:10;
yTrue = 0.5*x.^2 - 3*x + 2;              % 真实的二次函数
y = yTrue + 2*randn(size(x));            % 加入噪声的观测数据
% 分别用 1 次和 2 次多项式拟合
p1 = polyfit(x, y, 1);
p2 = polyfit(x, y, 2);
fprintf('一次拟合：y = %.3f x %+.3f\n', p1);
fprintf('二次拟合：y = %.3f x^2 %+.3f x %+.3f\n', p2);
% 计算拟合误差（均方根误差 RMSE）
rmse1 = sqrt(mean((polyval(p1, x) - y).^2));
rmse2 = sqrt(mean((polyval(p2, x) - y).^2));
fprintf('RMSE：一次 = %.3f，二次 = %.3f\n', rmse1, rmse2);
% 在更密的点上画出拟合曲线
xf = linspace(0, 10, 200);
figure;
plot(x, y, 'ko', 'MarkerFaceColor', 'y');   % 数据点
hold on;
plot(xf, polyval(p1, xf), 'b--', 'LineWidth', 1.5);
plot(xf, polyval(p2, xf), 'r-', 'LineWidth', 2);
hold off;
legend('观测数据', '一次拟合', '二次拟合', 'Location', 'northwest');
title('多项式曲线拟合');
xlabel('x'); ylabel('y');
grid on;
% 用二次模型预测 x = 12 处的值
pred = polyval(p2, 12)

% 示例 12：交互输入 input
% input(提示) 读取数值表达式；input(提示, 's') 按原样读取字符串
name = input('请输入你的名字：', 's');
a = input('请输入第一个数：');
b = input('请输入第二个数：');
fprintf('\n你好，%s！\n', name);
% 基本四则运算
fprintf('%g + %g = %g\n', a, b, a + b);
fprintf('%g - %g = %g\n', a, b, a - b);
fprintf('%g × %g = %g\n', a, b, a * b);
% 除法前先检查除数是否为 0
if b ~= 0
    fprintf('%g ÷ %g = %.4f\n', a, b, a / b);
else
    disp('除数为 0，无法计算除法。');
end
% 比较大小
if a > b
    fprintf('较大的数是 %g\n', a);
elseif a < b
    fprintf('较大的数是 %g\n', b);
else
    disp('两个数相等。');
end
% 求最大公约数（仅当输入为正整数时）
if all([a b] == round([a b])) && a > 0 && b > 0
    fprintf('最大公约数 gcd = %d\n', gcd(a, b));
end
